body.onloadscript:



if (Sepoa.request.SMR_NUMBER) { //팝업으로 띄웠을 시 이전 화면에서 가져오는 데이터로 SMR_NUMBER가 있는지 확인
    doQuery(Sepoa.request.SMR_NUMBER, 'Y');
}
window.onresize = resizePopup;

body.userscript:




         // 인감구분 변경시 현재구분과 비교하기 위해 사용, 이전 클릭되어 있던 인감구분을 저장

            //폼, smr_number등의 정보를 담는 변수



            //그리드 데이터의 정보를 담는 변수



            //날인서류인장리스트







            //새로 만든 요청이라면 Y












            switch (name) {
                case "SAVE":
                    doSave();
                    break;
                case "REAL_SEAL":
                    doRealSave();
                    break;
                case "APPROVAL_REQ":
                    doApprovalRequest();
                    break;
                case "MANAGER_REQUEST":
                    doManagerRequest();
                    break;
                case "MANAGER_ACCEPT":
                    doManagerAccept();
                    break;
                case "MANAGER_REJECT":
                    doManagerReject();
                    break;
                case "LEGAL_REQUEST":
                    doLegalRequest();
                    break;
                case "LEGAL_ACCEPT":
                    doLegalAccept();
                    break;
                case "LEGAL_REJECT":
                    doLegalReject();
                    break;
                case "COMPLETE":
                    doComplete();
                    break;
                case "BACK":
                    doBack();
                    break;
                default:
                    break;
            }




            // 채번 따서 $reqSealInfo에 채번넣고 기본셋팅
            $documentList = new Object(); //문서정보리스트
            $selectedSealList = new Object(); //인장리스트
            formObj.setValue('APPLY_TYPE', 'U');
            gridObj_title.innerHTML = Sepoa.cache.text.get('SLM_211.GRID_TITLE');
            gridObj_title.setAttribute('style', 'font-size:14px;padding-top: 15px;');
            gridObj.setColumnHidden(gridObj.getColIndexById('SEAL_TYPE_U'), false);
            gridObj.setColumnHidden(gridObj.getColIndexById('SEAL_TYPE_C'), true);
            gridObj.setColumnHidden(gridObj.getColIndexById('SEAL_TYPE'), true);
            gridObj.setColumnHidden(gridObj.getColIndexById('REAL_ATTACH_IMG'), true);
            gridObj.setColumnHidden(gridObj.getColIndexById('CALC_DOWN_CNT'), true);

            formObj2.setValue('FOOTER_FLAG', 1);
            formObj.setItemLabel("ELECTRON_FLAG", Sepoa.cache.text.get('SLM_211.ELECTRON_FLAG_U'));
            formObj.setItemLabel("REAL_FLAG", Sepoa.cache.text.get('SLM_211.REAL_FLAG_U'));

            if (!sUtils.workflow.check('US1638852635132')) { //파일다운로드 제한 모듈
                gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), 1); //저장횟수 숨김
                //gridObj.grid_required[gridObj.getColIndexById('COUNT')] = ''; //그리드 필수값에서 COUNT를 뺌
            }

            //전자 사용인감 모듈
            if (!sUtils.workflow.check('US1639451130271')) {
                formObj.hideItem("ELECTRON_FLAG");
                formObj.checkItem('REAL_FLAG');
            }

            //실물 사용인감 모듈
            if (!sUtils.workflow.check('US1639451350768')) {
                formObj.hideItem("REAL_FLAG");
                formObj.checkItem('ELECTRON_FLAG');
            }

            if (sUtils.ux.getRootScreenID() == 'SLM_220') {
	            if (!Sepoa.request.SMR_NUMBER) {
	            	isNew = true;
	            	var smrNumber = getDocumentNumber("SMR"); //채번
	            	formObj.setValue('ELECTRON_FLAG', 1);	// 전자인감을 기본으로 세팅
	            } else {
	            	isNew = false;
	            	var smrNumber = Sepoa.request.SMR_NUMBER;
	            }

                var smrNumber = Sepoa.request.SMR_NUMBER || getDocumentNumber("SMR"); //채번
                $reqSealInfo.SMR_NUMBER = smrNumber;
                formObj.setValue('SMR_NUMBER', smrNumber);

                initBtn();
            }

            if (!Sepoa.request.SMR_NUMBER) {
                 formObj.setValue('ADD_DATE', sUtils.date.getToday());
            }

			if (['NO_TARGET_U', 'NO_TARGET_UF', 'NO_TARGET_US', 'NO_TARGET_FN'].indexOf(Sepoa.request.screen) > -1) {
				setNoTargetMode(true);
            } else {
            	setNoTargetMode(false);
            }





            btnObj.forEachBtn(function(btnId) {
                if (btnId) {
                    btnObj.showButton(btnId, false);
                }
            });
            gridObj_btnObj.forEachBtn(function(btnId) {
                if (btnId) {
                    gridObj_btnObj.showButton(btnId, false);
                }
            });




            document.getElementById('cREwYmeIzYyYmeQRSg').style.display = 'inline-block';
            document.getElementById('KfKibmeVhylbmedHrV').style.display = 'inline-block';
            formObj.setReadonly('ADD_DATE', true);




            // 처음에 모든 버튼을 숨기고 상황에 맞는 버튼 표출
            hideAllButtons();
            formObj.setReadonly('ADD_DATE', true);

            if (SCREEN_MODE == 'APP') {
                formObj._apiConnector('detachAllEvents', []);
                formObj.setViewMode(true);
                formObj2.setViewMode(true);
                gridObj.setReadOnly(true);
                showButtonArea();
   			} else if (['', Sepoa.info.ID].indexOf(formObj.getValue('ADD_USER_ID')) > -1 && (smrStatus == 'T' || (SCREEN_MODE == 'MY_REQ' && VIEW_MODE == 'EDITOR'))) { //임시저장 또는 요청내역에서 수정하는 경우
                VIEW_MODE == 'EDITOR';
                formObj.setViewMode(false);
                formObj2.setViewMode(false);
                gridObj.setReadOnly(false);
                gridObj.setColumnHidden(gridObj.getColIndexById('MANAGE_IMG'), 0); //인감 선택버튼

                if (moveFlag == 'N') { //기존 임시저장일 경우 N, Y는 요청내역에서 들어올 시 doquery에서 Y을 들고 들어옴 
                    btnObj.showButton('back', true);
                }
                gridObj.setColumnHidden(gridObj.getColIndexById('MANAGE_IMG'), 0); //관리부서 선택버튼 표출
                gridObj_btnObj.showButton('rowadd,rowdelete', true); //행 추가,삭제버튼 표출
                // 임시저장 상태일 때 다음 모듈에 따라 표출될 버튼이 다름
                // PARENT: 어느 페이지 안에서 서비스를 실행하는지 확인

                if (['USR','USR_US','USR_UF','USR_FN', 'CSR', 'NO_TARGET_U', 'NO_TARGET_UF', 'NO_TARGET_US', 'NO_TARGET_FN'].indexOf(Sepoa.request.screen) > -1) { // 날인신청 팝업
                    btnObj.showButton('write_done', true);
                    if (Sepoa.request.SUBJECT) formObj.setValue('SUBJECT', decodeURIComponent(escape(atob(Sepoa.request.SUBJECT.replaceAll(' ', '+')))));
                    if (['NO_TARGET_U', 'NO_TARGET_UF', 'NO_TARGET_US', 'NO_TARGET_FN'].indexOf(Sepoa.request.screen) > -1 && smrStatus == 'T') {	// 사외문서 임시저장이라면
                    	gridObj_btnObj.forEachBtn(function(btnId) { if (btnId) { gridObj_btnObj.showButton(btnId, false); }});
                    }
                    showButtonArea();
                } else { // 메뉴에서 들어온 경우
                    doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectNextModule', {
                        ALIAS: 'CREATE',
                        PARENT: 'USW'
                    }, function(so) {
                        if (so.status == 1) {
                            var moduleArr = JSON.parse(so.result[0]);
                            var nextModule = moduleArr.MODULE;

                            switch (nextModule) {
                                case "USW1635987860041":
                                    // 결재
                                    btnObj.showButton('save,approval_req', true);
                                    break;
                                case "USW1637309480717":
                                    // 인감담당자 승인
                                    btnObj.showButton('save,manager_request', true);
                                    break;
                                case "USW1635987860553":
                                    // 인감책임자 승인
                                    btnObj.showButton('save,legal_request', true);
                                    break;
                                case "USW1635987861018":
                                    // 완료
                                    btnObj.showButton('save,complete', true);
                                    break;
                                default:
                                    break;
                            }

                            if (!isNew && smrStatus == 'T') {	// 임시저장
			                    doServiceAjax('sepoa.svc.seal.cbo_002.SepoaReqSealServiceCbo', 'CONNECTION', 'checkOrigin', { // 어디서 작성했는지 조회
					                SMR_NUMBER: $reqSealInfo.SMR_NUMBER
						            }, function(so) {
						                if (so.status == 1) {
						                	const erpCode = so.result[0];
						                	if (erpCode != 'EASYSEAL') {	// 그룹웨어에서 시작했고 지금은 전자인장에서 들어왔다면
						                		gridObj_btnObj.forEachBtn(function(btnId) { if (btnId) { gridObj_btnObj.showButton(btnId, false); }});
									            btnObj.showButton('save', false);
						                		btnObj.showButton('approval_req', false);
						                	}
						                }
						                showButtonArea();
					                }
					            );
		                    } else {
	                            showButtonArea();
		                    }

                        } else {
                            Alert(Sepoa.cache.text.get("MESSAGE.1002"));
                        }
                    });
                }

            } else if (smrStatus != 'T' || ['', Sepoa.info.ID].indexOf(formObj.getValue('ADD_USER_ID')) == -1) {
                var alias = '';
                //formObj._apiConnector('detachAllEvents', []); //폼의 이벤트와 분리
                formObj.setViewMode(true);
                formObj2.setViewMode(true);
                gridObj.setReadOnly(true);
                gridObj.setColumnHidden(gridObj.getColIndexById('MANAGE_IMG'), 1); //인감 선택버튼 숨김

                if (Sepoa.request.SMR_NUMBER || ['APPR_TURN', 'APPR_DONE'].indexOf(SCREEN_MODE) > -1) {
                    btnObj.showButton('back', false);
                } else {
                    btnObj.showButton('back', true);
                }

                // 처리현황
                if (SCREEN_MODE == 'TODO') { // 날인요청 처리대상
                    if (smrStatus == 'G' && Sepoa.info.CTRL_CODE.indexOf('SEAL_CONFIRM') > -1) {
                        // 인감책임자 승인대기상태면서 인감책임자인 경우
                        btnObj.showButton('legal_accept,legal_reject', true);
                    } else if (SCREEN_MODE == 'TODO' && smrStatus == 'W' && btnFlag) {
                        // 인감담당자 승인 진행중이며 true(관리자)일 경우
                        btnObj.showButton('manager_accept,manager_reject', true);
                    }
                }

                if (smrStatus == 'C') { //완료
                    gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), 1);
                    if (!sUtils.workflow.check('US1638852635132')) { //모듈이 꺼져 있다면
                        gridObj.setColumnHidden(gridObj.getColIndexById('CALC_DOWN_CNT'), 1); //다운로드 횟수 숨김
                        //gridObj.grid_required[gridObj.getColIndexById('COUNT')] = ''; //필수체크 처리
                    } else {
                        gridObj.setColumnHidden(gridObj.getColIndexById('CALC_DOWN_CNT'), 0); //다운로드 횟수 표출
                    }

                    if (formObj.getValue('REAL_FLAG') == 1) {
                        if (['NO_TARGET_U', 'NO_TARGET_UF', 'NO_TARGET_US', 'NO_TARGET_FN'].indexOf(Sepoa.request.screen) > -1) btnObj.showButton('real_seal', false);
                        gridObj.setColumnHidden(gridObj.getColIndexById('CALC_DOWN_CNT'), 1);
                    }
                }
                showButtonArea();
            }




            if (mode) SCREEN_MODE = mode;




            $documentList = {};
            $reqSealInfo = {};
            formObj.clear();
            formObj2.clear();
            gridObj.clearAll();
            moveFlag = move;
            VIEW_MODE = viewMode || '';
            isNew = false;

            if (smrNumber) {
                $reqSealInfo.SMR_NUMBER = smrNumber;
                formObj.setValue('SMR_NUMBER', smrNumber);
            }

            doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectRequestInfo', { // 날인요청의 정보를 조회
                SMR_NUMBER: smrNumber,
                APPLY_TYPE: 'U'
            }, function(so) {
                if (so.status == 1) {
                    var reqData = JSON.parse(so.result[0]);
                    var reqSealInfo = reqData[0].REQ_SEAL_INFO; //객체정보
                    var documentList = reqData[0].DOCUMENT_LIST; //서류문서
                    var selectedSealList = reqData[0].SELECTED_SEAL_LIST; //인감조회
                    var btnFlag = false;
                    formObj.dataMapper(reqSealInfo, 'JSON');
                    formObj2.dataMapper(reqSealInfo, 'JSON');
                    $reqSealInfo.SMR_NUMBER = reqSealInfo.SMR_NUMBER;
                    smrStatus = reqSealInfo.SMR_STATUS;

                    if (smrStatus == 'T' && ['', Sepoa.info.ID].indexOf(reqSealInfo.ADD_USER_ID) > -1 && ['USR','USR_US','USR_UF','USR_FN', 'NO_TARGET_U', 'NO_TARGET_UF', 'NO_TARGET_US', 'NO_TARGET_FN'].indexOf(Sepoa.request.screen) > -1) {
                    	VIEW_MODE = 'EDITOR';
                    }

                    // 구분 세팅
                    var reFlagDetail = reqSealInfo.RE_DETAIL.split(',');
                    for (var i in reFlagDetail) {
                        switch (reFlagDetail[i]) {
                            case "E":
                                formObj.setValue('ELECTRON_FLAG', 1);
                                continue;
                            case "R":
                                formObj.setValue('REAL_FLAG', 1);
                                gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), true);
                                continue;
                        }
                    }

                    if (smrStatus == 'C') {
                        if (formObj.getValue('REAL_FLAG') == 1) { //실물날인일 경우
                        	if (['NO_TARGET_U', 'NO_TARGET_UF', 'NO_TARGET_US', 'NO_TARGET_FN'].indexOf(Sepoa.request.screen) > -1) {	// 사외문서
                        		gridObj.setColumnHidden(gridObj.getColIndexById('REAL_ATTACH_IMG'), true);
                        	} else {
	                            gridObj.setColumnHidden(gridObj.getColIndexById('REAL_ATTACH_IMG'), false);
                        	}
                        } else {
                            gridObj.setColumnHidden(gridObj.getColIndexById('REAL_ATTACH_IMG'), true);
                        }
                    }

                    //콤보 불러오기
                    var useArray = Sepoa.cache.combo.get('SL0047,' + Sepoa.info.HOUSE_CODE + '#' + Sepoa.info.COMPANY_CODE);
                    //배열의 특정값을 찾는 조건을 callback함수를 통해 전달하여 조건에 맞는 값 중 첫번째 값을 리턴한다.
                    //EX ) arr.find(callback(element[,index[,array]])[,thisArg])
                    //item = 현재 처리중인 배열의 element, idx = 현재 처리중인 배열의 인덱스
                    var useName = useArray.find((item, idx) => {
                        return item.value == reqSealInfo.REQ_SEAL_USE_TYPE; //요청된 용도와 해당 값이 같으면
                    });
                    // 용도 세팅
                    if (useName != null && useName != '') {
                        formObj.setValue('USE_NUMBER', useName.text);
                        formObj.setValue('SEAL_USE_TYPE', useName.value);
                    }
                    // 법적효력문구 세팅
                    var legalWatermark = reqSealInfo.LEGAL_WATERMARK;
                    if (legalWatermark == 'K') {
                        formObj2.setValue('FOOTER_FLAG', 1);
                    } else if (legalWatermark == 'E') {
                        formObj2.setValue('FOOTER_FLAG_EN', 1);
                    }

                    // 날인대상서류 세팅
                    for (var i in documentList) {
                        var data = documentList[i];
                        var maxRowId = dhx4.newId();
                        // 그리드 데이터 셋팅

                        gridObj.addRow(maxRowId, '', gridObj.getRowsNum());
                        gridObj.cells(maxRowId, gridObj.getColIndexById('SMR_SEQ_TEMP')).setValue('temp_' + maxRowId);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('SMD_NUMBER')).setValue(data.SMD_NUMBER); //날인서류채번
                        gridObj.cells(maxRowId, gridObj.getColIndexById('COUNT')).setValue(data.COUNT);
                        //gridObj.cells(maxRowId, gridObj.getColIndexById('RE_DETAIL')).setValue(reqSealInfo.RE_DETAIL);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('DOWN_COUNT')).setValue(data.DOWN_COUNT);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('SUBJECT')).setValue(data.SUBJECT);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('SEAL_TYPE_U')).setValue(data.SEAL_TYPE);
                        //gridObj.cells(maxRowId, gridObj.getColIndexById('SEAL_TYPE')).setValue(data.SEAL_TYPE);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('REAL_ATTACH_NO')).setValue(data.REAL_ATTACH_NO);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('DOC_NUMBER')).setValue(data.SMR_NUMBER + '_' + data.SMD_NUMBER);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('CALC_DOWN_CNT')).setValue(Number(data.COUNT) - Number(data.DOWN_COUNT) + ' / ' + Number(data.COUNT));
                        gridObj.cells(maxRowId, gridObj.getColIndexById('ITEMS_JSON')).setValue(data.ITEMS_JSON.replace(/\"/gi, '~REPTOQM~'));
                        gridObj.cells(maxRowId, gridObj.getColIndexById('MARK_COUNT')).setValue(data.MARK_COUNT);
                        //gridObj.cells(maxRowId, gridObj.getColIndexById('RE_DETAIL')).setValue(data.RE_DETAIL);

                        if (gridObj.cells(maxRowId, gridObj.getColIndexById('DOC_NUMBER')).getValue() != '') {
                            gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH_IMG')).setIcon('ATTACH_IMG2');
                            gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH_IMG')).cell.children[0].style = 'filter:none';
                        }

                        if (gridObj.cells(maxRowId, gridObj.getColIndexById('REAL_ATTACH_NO')).getValue() != '') {
                            gridObj.cells(maxRowId, gridObj.getColIndexById('REAL_ATTACH_IMG')).setIcon('ATTACH_IMG2');
                            gridObj.cells(maxRowId, gridObj.getColIndexById('REAL_ATTACH_IMG')).cell.children[0].style = 'filter:none';
                        }

                        gridObj.showRow(maxRowId);

                        $documentList[data.SMD_NUMBER] = data;
                        $selectedSealList[data.SMD_NUMBER] = {};
                        var sealData = [];
                        //인장 리스트
                        for (var j in selectedSealList) {
                            if (data.SMD_NUMBER == selectedSealList[j].SMD_NUMBER) {
                                selectedSealList[j].ITEM_NAME = selectedSealList[j].SUBJECT;
                                sealData.push(selectedSealList[j]);
                                gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_MG_DEPT")).setValue(selectedSealList[j].DEPT_NAME);
                                gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_MG_DEPT_CODE")).setValue(selectedSealList[j].SEAL_MG_DEPT);
                                sealMgId.push(selectedSealList[j].SEAL_MG_USER_ID);

                                if ((smrStatus == 'W' && Sepoa.info.ID == selectedSealList[j].SEAL_MG_USER_ID && selectedSealList[j].ACCEPT_FLAG == 'N') ||
                                    smrStatus == 'G' && Sepoa.info.CTRL_CODE.indexOf('MANAGE_CONFIRM') > -1 ||
                                    smrStatus == 'W' && Sepoa.info.ID == selectedSealList[j].RECE_USER_ID && selectedSealList[j].ACCEPT_FLAG == 'N'
                                ) {
                                    btnFlag = true;
                                }

                                var orgSealName = gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_NAME")).getValue();
                                var sealName = selectedSealList[j].SUBJECT;
                                if (orgSealName != '') sealName = orgSealName + ',' + sealName;
                                gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_NAME")).setValue(sealName);

                                var orgManageNo = gridObj.cells(maxRowId, gridObj.getColIndexById("MANAGE_NUMBER")).getValue();
                                var manageNo = selectedSealList[j].MANAGE_NUMBER;
                                if (orgManageNo != '') manageNo = orgManageNo + ',' + manageNo;
                                gridObj.cells(maxRowId, gridObj.getColIndexById("MANAGE_NUMBER")).setValue(manageNo);

                                var orgCategoryName = gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_CATEGORY")).getValue();
                                var categoryName = selectedSealList[j].CATEGORY_NAME;
                                if (orgCategoryName != '') categoryName = orgCategoryName + ',' + categoryName;
                                gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_CATEGORY")).setValue(categoryName);

                                var orgCategoryCode = gridObj.cells(maxRowId, gridObj.getColIndexById("CATEGORY_CODE")).getValue();
                                var categoryCode = selectedSealList[j].CATEGORY_CODE;
                                if (orgCategoryCode != '') categoryCode = orgCategoryCode + ',' + categoryCode;
                                gridObj.cells(maxRowId, gridObj.getColIndexById("CATEGORY_CODE")).setValue(categoryCode);

                            }
                        }
                        $documentList[data.SMD_NUMBER].SELECT_SEAL_LIST = sealData;
                        $selectedSealList[data.SMD_NUMBER].SELECT_SEAL_LIST = sealData;
                    }

                    initBtn(btnFlag);

            		if (gridObj.getRowsNum() && gridObj.gridGetCellValueId(gridObj.getRowId(0), 'SMD_NUMBER').startsWith('NO_DOC')) {
            			setNoTargetMode(true);	// 사외문서(날인대상서류 없음)
            		} else {
            			setNoTargetMode(false);
            		}

                } else {
                    Alert(Sepoa.cache.text.get("MESSAGE.1002"));
                }
            });




            if (SCREEN_MODE == 'GW') {
                callFunction('p', 'doGroupBack', []);
            } else {
                callFunction('p', 'doBack', []);
            }
            pageClear();




            if (!formObj.validate() || (['NO_TARGET_U', 'NO_TARGET_UF', 'NO_TARGET_US', 'NO_TARGET_FN'].indexOf(Sepoa.request.screen) == -1 && !gridObj.validate())) {
                Alert(Sepoa.cache.text.get('MESSAGE.0002'));
                return;
            }
            var formData = Object.assign(formObj.getFormData(), formObj2.getFormData());
            // E 전자 사용인감
            var elecFlag = formObj.getValue('ELECTRON_FLAG');
            // R 실물 사용인감
            var realFlag = formObj.getValue('REAL_FLAG');

            if (elecFlag == "1") { //전자사용인감이 선택되었다면
                var flagArr = [];
                formData.RE_FLAG = "E";
                elecFlag = elecFlag == "1" ? "E" : "";
                if (elecFlag != "") {
                    flagArr.push(elecFlag);
                }

                formData.RE_DETAIL = flagArr.join(","); // ,를 사용하여 배열로 작성
